// ⚙️ CONFIG — the only node you need to edit.
const config = {
  // Your Jira Cloud site. Must match the Jira credential.
  jiraBaseUrl: 'https://your-company.atlassian.net',

  // Requirement tickets (stories, tasks, epics…) that are ready for a test plan.
  // Keep the label filter: it stops a ticket getting two test plans.
  jql: 'project = DEV AND issuetype in (Story, Task) AND status = "Ready for QA" AND (labels is EMPTY OR labels not in (ai-test-plan-created, ai-needs-human)) ORDER BY updated ASC',
  maxIssuesPerRun: 3,

  // Extra fields that hold requirements text, read together with the description.
  // e.g. ['customfield_10050'] for an "Acceptance criteria" field. [] = description only.
  extraRequirementFields: [],

  testPlan: {
    projectKey: 'QA',                // project where test plans are created
    issueType: 'Test Plan',          // Xray "Test Plan", or e.g. 'Task' without Xray
    summaryPrefix: 'Test Plan: ',
    linkType: 'Relates',             // issue link type between the test plan and the requirement
    copyAssignee: true,              // assign the plan to the requirement's assignee
    statusAfterCreate: '',           // e.g. 'Done' to hand straight to "AI Test Case Generator"; '' = leave for review
  },

  labels: {
    requirementDone: 'ai-test-plan-created', // added to the requirement ticket
    testPlan: 'ai-test-plan',                // added to the created test plan
    needsHuman: 'ai-needs-human',            // added to the requirement when no valid plan could be made
  },

  maxTests: 10,
  exitCriteria: [
    'All priority 3 test cases passed.',
    'No critical defects open.',
  ],

  model: 'gpt-5.5',
};

// Manual test on one ticket: set a key here, then press "Test workflow". Ignored on scheduled runs.
const testIssueKey = '';
config.searchJql = $('▶ Test run').isExecuted && testIssueKey ? `key = ${testIssueKey}` : config.jql;
return [{ json: config }];

// ---- helpers ----
function adfToText(node) {
  // Jira Cloud (API v3) returns rich text as ADF. This turns it into plain text an LLM can read.
  if (node == null) return '';
  if (typeof node === 'string') return node;
  if (Array.isArray(node)) return node.map(adfToText).join('');
  switch (node.type) {
    case 'text': {
      const link = (node.marks || []).find((m) => m.type === 'link');
      const href = link?.attrs?.href;
      return href && href !== node.text ? `${node.text} (${href})` : (node.text || '');
    }
    case 'hardBreak': return '\n';
    case 'mention': return node.attrs?.text || '@user';
    case 'emoji': return node.attrs?.text || '';
    case 'inlineCard':
    case 'blockCard': return node.attrs?.url || '';
    case 'media': return '[attachment]';
    case 'paragraph':
    case 'heading': return adfToText(node.content) + '\n';
    case 'listItem': return '- ' + adfToText(node.content).trim() + '\n';
    case 'bulletList':
    case 'orderedList': return adfToText(node.content) + '\n';
    case 'tableRow': return '| ' + (node.content || []).map((c) => adfToText(c.content).trim().replace(/\n+/g, ' ')).join(' | ') + ' |\n';
    case 'codeBlock': return '```\n' + adfToText(node.content) + '\n```\n';
    case 'rule': return '---\n';
    default: return adfToText(node.content);
  }
}
// ---- end helpers ----

const cfg = $('⚙️ Config').first().json;
const issues = $input.first().json.issues || [];
return issues.map((issue) => {
  const f = issue.fields || {};
  const extra = (cfg.extraRequirementFields || [])
    .map((id) => adfToText(f[id]).trim())
    .filter(Boolean);
  const requirements = [adfToText(f.description).trim(), ...extra].filter(Boolean).join('\n\n');
  return {
    json: {
      key: issue.key,
      summary: f.summary || '',
      requirements: requirements || '(no description)',
      assigneeAccountId: f.assignee?.accountId || '',
    },
  };
});

