// ---- helpers ----
function getLlmText(json) {
  // Works with the OpenAI "Message a model" node and most other model nodes.
  if (typeof json?.output === 'string') return json.output;
  if (Array.isArray(json?.output)) {
    for (const part of json.output) {
      if (Array.isArray(part?.content)) {
        const t = part.content.find((c) => c?.text != null);
        if (t) return typeof t.text === 'string' ? t.text : JSON.stringify(t.text); // JSON output mode returns an object
      }
    }
  }
  if (typeof json?.text === 'string') return json.text;
  if (typeof json?.content === 'string') return json.content;
  if (Array.isArray(json?.content)) {
    // Anthropic and similar: the text can come after a "thinking" block
    const t = json.content.find((c) => c?.type === 'text' && typeof c.text === 'string');
    if (t) return t.text;
  }
  if (typeof json?.merged_response === 'string' && json.merged_response) return json.merged_response;
  if (typeof json?.message?.content === 'string') return json.message.content;
  if (typeof json?.choices?.[0]?.message?.content === 'string') return json.choices[0].message.content;
  throw new Error('Could not find the text in the model response. Check the model node output.');
}

function parseLlmJson(text) {
  // Returns the parsed object, or null if the model did not return valid JSON.
  const cleaned = String(text ?? '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  try { return JSON.parse(cleaned); } catch (e) { /* try the first {...} block */ }
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (!match) return null;
  try { return JSON.parse(match[0]); } catch (e) { return null; }
}
// ---- end helpers ----

// Checks the plan with code (not just the reviewer model), then renders it as a Jira document.
const cfg = $('⚙️ Config').first().json;
const req = $('Prepare requirement').item.json;

const isPlan = (p) => p && typeof p === 'object' && Array.isArray(p.tests) && p.tests.length > 0;
let plan = parseLlmJson(getLlmText($json));
let source = 'reviewed';
if (!isPlan(plan)) {
  plan = parseLlmJson(getLlmText($('Write test plan').item.json));
  source = 'first draft (the review step did not return valid JSON)';
}
if (!isPlan(plan)) {
  return { json: { ...req, ok: false, problem: 'The model did not return a valid test plan (JSON with at least one test).' } };
}

const text = (v, fb = 'Assumption: not specified in the requirement.') => String(v ?? '').trim() || fb;
const list = (v) => (Array.isArray(v) ? v : String(v ?? '').split(/\n|;/))
  .map((s) => String(s ?? '').replace(/^[-*•]\s*/, '').trim()).filter(Boolean);
const level = (v) => ([1, 2, 3].includes(Number(v)) ? Number(v) : 2);

const seen = new Set();
const tests = plan.tests
  .map((t) => ({ testName: String(t?.testName ?? '').trim(), priority: level(t?.priority), weight: level(t?.weight) }))
  .filter((t) => t.testName && !seen.has(t.testName.toLowerCase()) && seen.add(t.testName.toLowerCase()))
  .slice(0, cfg.maxTests);

const p = {
  featureName: text(plan.featureName, req.summary),
  featureSummary: text(plan.featureSummary),
  objective: text(plan.objective),
  inScope: list(plan.inScope),
  outOfScope: list(plan.outOfScope),
  testEnvironment: list(plan.testEnvironment),
  preconditions: list(plan.preconditions),
  tests,
};

// ---- Atlassian Document Format (Jira Cloud rich text) ----
const t = (s, marks) => (marks ? { type: 'text', text: String(s), marks } : { type: 'text', text: String(s) });
const para = (...c) => ({ type: 'paragraph', content: c.length ? c : [] });
const bullets = (items) => ({
  type: 'bulletList',
  content: (items.length ? items : ['Assumption: not specified in the requirement.'])
    .map((s) => ({ type: 'listItem', content: [para(t(s))] })),
});
const cell = (content, header = false) => ({ type: header ? 'tableHeader' : 'tableCell', attrs: {}, content: Array.isArray(content) ? content : [para(t(content))] });
const row = (cells) => ({ type: 'tableRow', content: cells });
const table = (rows) => ({ type: 'table', attrs: { isNumberColumnEnabled: false, layout: 'default' }, content: rows });
const heading = (s) => ({ type: 'heading', attrs: { level: 3 }, content: [t(s)] });
const reqUrl = `${cfg.jiraBaseUrl}/browse/${req.key}`;

const description = {
  type: 'doc', version: 1,
  content: [
    para(t('Requirement: '), t(req.key, [{ type: 'link', attrs: { href: reqUrl } }]), t(` — ${req.summary}`)),
    heading('Description'),
    table([
      row([cell('Section', true), cell('Details', true)]),
      row([cell('Feature name'), cell(p.featureName)]),
      row([cell('Feature summary'), cell(p.featureSummary)]),
      row([cell('Objective'), cell(p.objective)]),
      row([cell('In scope'), cell([bullets(p.inScope)])]),
      row([cell('Out of scope'), cell([bullets(p.outOfScope)])]),
      row([cell('Test environment'), cell([bullets(p.testEnvironment)])]),
      row([cell('Preconditions'), cell([bullets(p.preconditions)])]),
    ]),
    { type: 'rule' },
    heading('Test Coverage and Traceability'),
    para(t('Priority and weight: 1 = lowest, 3 = highest.')),
    table([
      row([cell('Test Name', true), cell('Priority (1-3)', true), cell('Weight (1-3)', true)]),
      ...p.tests.map((x) => row([cell(x.testName), cell(String(x.priority)), cell(String(x.weight))])),
    ]),
    { type: 'rule' },
    heading('Exit Criteria'),
    bullets(cfg.exitCriteria || []),
  ],
};

const fields = {
  project: { key: cfg.testPlan.projectKey },
  issuetype: { name: cfg.testPlan.issueType },
  summary: (cfg.testPlan.summaryPrefix + req.summary).slice(0, 254),
  description,
  labels: [cfg.labels.testPlan],
};
if (cfg.testPlan.copyAssignee && req.assigneeAccountId) fields.assignee = { accountId: req.assigneeAccountId };

return { json: { ...req, ok: true, source, testCount: p.tests.length, createBody: { fields } } };

// Finds the transition that leads to the configured status NAME.
const key = $('Create test plan').item.json.key;
const target = String($('⚙️ Config').first().json.testPlan.statusAfterCreate).trim();
const list = $json.transitions || [];
const hit = list.find((t) => (t.to?.name || '').toLowerCase() === target.toLowerCase())
  || list.find((t) => (t.name || '').toLowerCase() === target.toLowerCase());
if (!hit) {
  const reachable = list.map((t) => t.to?.name).filter(Boolean).join(', ') || 'none';
  throw new Error(`Can't move ${key} to "${target}": not reachable from its current status (reachable: ${reachable}). Check the status name in ⚙️ Config.`);
}
return { json: { key, transitionId: hit.id, status: hit.to?.name || target } };
